import {cms} from '@/cms'
import {Event} from '@/schema'

// Events in 2026 that cost less than 20, or have no price set
const events = await cms.find({
  type: Event,
  filter: {
    date: {gte: '2026-01-01', lt: '2027-01-01'},
    price: {or: [{lt: 20}, null]}
  }
})

import {cms} from '@/cms'
import {BlogPost} from '@/schema'

const authorId = '2g8FtRVKqrzBhqNzjRvCTJlTWkn'
const categoryIds = ['2g8Fu0PUfDUNMH4KNvqHYCcRCyX', '2g8Fu4lyGY6m5sN4YhAp8ag0WcY']

// Posts by one author: a single entry link stores {_entry: id}
await cms.find({type: BlogPost, filter: {author: {has: {_entry: authorId}}}})

// Posts in any of these categories
await cms.find({
  type: BlogPost,
  filter: {categories: {includes: {_entry: {in: categoryIds}}}}
})

// Posts tagged "release"
await cms.find({type: BlogPost, filter: {tags: {includes: 'release'}}})

import {cms} from '@/cms'
import {BlogPost} from '@/schema'

// Featured, or tagged as a release
await cms.find({
  type: BlogPost,
  filter: {or: [{featured: true}, {tags: {includes: 'release'}}]}
})

// Posts in every one of these categories
const categoryIds = ['2g8Fu0PUfDUNMH4KNvqHYCcRCyX', '2g8Fu4lyGY6m5sN4YhAp8ag0WcY']
await cms.find({
  type: BlogPost,
  filter: {
    and: categoryIds.map(id => ({categories: {includes: {_entry: id}}}))
  }
})

import {cms} from '@/cms'
import {BlogPost} from '@/schema'

export async function listPosts(tag?: 'news' | 'release', from?: string) {
  return cms.find({
    type: BlogPost,
    filter: {
      tags: tag ? {includes: tag} : undefined,
      publishDate: from ? {gte: from} : undefined
    }
  })
}

import {cms} from '@/cms'
import {Query} from 'alinea'

export async function searchSite(terms: string, locale: string) {
  return cms.find({
    search: terms,
    locale,
    take: 20,
    select: {
      title: Query.title,
      url: Query.url,
      snippet: Query.snippet('<mark>', '</mark>', '…', 24)
    }
  })
}
